-- QuoteCore+ practice-priced roofing starter libraries v3 (2026-11-14).
-- Additive to 20261114160000 and 20261114180000. Staging ONLY until verified.
-- Master rows can be edited in Supabase Table Editor; customer copies are independent.
-- Five libraries / 35 essential practice-priced components, reference USD 2026.
-- Rates are RESEARCH-INFORMED ILLUSTRATIVE COST ALLOCATIONS, not supplier quotes.
-- All prices exclude VAT/sales tax, overhead, profit, permits and freight.
-- The existing engine applies waste to both material and labour, as disclosed in UI.

ALTER TABLE public.pricing_starter_price_values ADD COLUMN IF NOT EXISTS waste_kind text
  NOT NULL DEFAULT 'none' CHECK (waste_kind IN ('none','percent','fixed'));
ALTER TABLE public.pricing_starter_price_values ADD COLUMN IF NOT EXISTS waste_value numeric(12,4)
  CHECK (waste_value IS NULL OR waste_value >= 0);
ALTER TABLE public.pricing_starter_price_values ADD COLUMN IF NOT EXISTS reference_unit text NOT NULL DEFAULT 'm²';
ALTER TABLE public.pricing_starter_price_values ADD COLUMN IF NOT EXISTS provenance text NOT NULL DEFAULT '';
ALTER TABLE public.pricing_starter_price_values ADD COLUMN IF NOT EXISTS researched_at date;
ALTER TABLE public.pricing_starter_price_sets ADD COLUMN IF NOT EXISTS template_version integer NOT NULL DEFAULT 1;
ALTER TABLE public.pricing_starter_price_sets ADD COLUMN IF NOT EXISTS demo_only boolean NOT NULL DEFAULT true;
ALTER TABLE public.pricing_starter_price_sets ADD COLUMN IF NOT EXISTS benchmark_market text NOT NULL DEFAULT '';

-- Separate master template edits from imported customer-owned copies.
ALTER TABLE public.component_library ADD COLUMN IF NOT EXISTS pricing_setup_practice boolean NOT NULL DEFAULT false;
ALTER TABLE public.component_library ADD COLUMN IF NOT EXISTS pricing_setup_template_slug text;
ALTER TABLE public.component_library ADD COLUMN IF NOT EXISTS pricing_setup_template_version integer;
ALTER TABLE public.component_library ADD COLUMN IF NOT EXISTS pricing_setup_example_currency text;
ALTER TABLE public.component_library ADD COLUMN IF NOT EXISTS pricing_setup_price_set_id uuid REFERENCES public.pricing_starter_price_sets(id) ON DELETE SET NULL;
ALTER TABLE public.component_library ADD COLUMN IF NOT EXISTS pricing_setup_verified_at timestamptz;
ALTER TABLE public.component_library ADD COLUMN IF NOT EXISTS pricing_setup_verified_by uuid;
CREATE INDEX IF NOT EXISTS component_library_practice_by_company_idx ON public.component_library(company_id,pricing_setup_practice)
  WHERE pricing_setup_practice = true;

-- The snapshot deliberately remains a practice quote even when the master component is later verified.
ALTER TABLE public.quote_components ADD COLUMN IF NOT EXISTS pricing_setup_practice_snapshot boolean NOT NULL DEFAULT false;
CREATE INDEX IF NOT EXISTS quote_components_practice_idx ON public.quote_components(quote_id)
  WHERE pricing_setup_practice_snapshot = true;

-- Copies of example-priced components may be used for internal practice quotes.
-- A quote containing any such component may not acquire or activate a customer acceptance link.
CREATE OR REPLACE FUNCTION public.pricing_setup_mark_quote_component_practice()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF NEW.component_library_id IS NOT NULL AND EXISTS (
  SELECT 1 FROM public.component_library cl
  JOIN public.quotes q ON q.id=NEW.quote_id AND q.company_id=cl.company_id
  WHERE cl.id=NEW.component_library_id AND cl.pricing_setup_practice = true
 ) THEN
  -- Do not introduce practice prices into a previously shared/sent customer quote.
  IF EXISTS (SELECT 1 FROM public.quotes q WHERE q.id=NEW.quote_id AND
    (q.acceptance_token IS NOT NULL OR q.job_status IN ('sent','viewed','accepted'))) THEN
   RAISE EXCEPTION 'Cannot add practice pricing to a customer-facing quote. Start a new unsent practice quote.' USING ERRCODE='23514';
  END IF;
  NEW.pricing_setup_practice_snapshot := true;
 END IF;
 -- Never clear practice_snapshot when the linked library component is edited/deleted.
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS pricing_setup_quote_component_snapshot ON public.quote_components;
CREATE TRIGGER pricing_setup_quote_component_snapshot
BEFORE INSERT OR UPDATE OF component_library_id ON public.quote_components
FOR EACH ROW EXECUTE FUNCTION public.pricing_setup_mark_quote_component_practice();

CREATE OR REPLACE FUNCTION public.pricing_setup_block_practice_quote_send()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF (NEW.acceptance_token IS NOT NULL AND (OLD.acceptance_token IS NULL OR NEW.acceptance_token IS DISTINCT FROM OLD.acceptance_token))
  OR (NEW.acceptance_token_expires_at IS NOT NULL AND NEW.acceptance_token_expires_at IS DISTINCT FROM OLD.acceptance_token_expires_at)
  OR (NEW.job_status IN ('sent','viewed','accepted') AND NEW.job_status IS DISTINCT FROM OLD.job_status)
 THEN
  IF EXISTS (SELECT 1 FROM public.quote_components qc
       WHERE qc.quote_id=NEW.id AND qc.pricing_setup_practice_snapshot = true) THEN
   RAISE EXCEPTION 'Practice pricing cannot be sent to customers. Create a fresh quote from verified pricing.' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS pricing_setup_practice_quote_send_guard ON public.quotes;
CREATE TRIGGER pricing_setup_practice_quote_send_guard
BEFORE UPDATE ON public.quotes
FOR EACH ROW EXECUTE FUNCTION public.pricing_setup_block_practice_quote_send();

